using System.Text.Json;
using YoshiWorkshop;
string pc=Path.GetFullPath(args[0]),outdir=Path.Combine(pc,"build/editor-0180");Directory.CreateDirectory(outdir);var rom=new VanillaRom(new SpecialContentRunner(pc).OriginalRom);int rejected=0;
void Need(bool v,string msg){if(!v)throw new Exception(msg);}
void Reject(Action a){try{a();}catch(InvalidDataException){rejected++;return;}throw new Exception("Invalid group operation accepted");}
string Snapshot(LevelProject p)=>JsonSerializer.Serialize(p,ProjectStore.Json);
var level=rom.CloneLevel(43);var source=new List<Placement>();
for(int i=0;i<6;i++){var p=rom.CreatePlacement((ushort)(0x4F00+i));p.X=200+i*40;p.Y=320;level.Objects.Add(p);source.Add(p);}
var clip=ObjectGroups.Copy(source,43,43);var original=source.Select(p=>(p.X,p.Y)).ToArray();source[0].X+=8;
var prepared=ObjectGroups.PreparePaste(rom,level,43,clip,600,400);Need(prepared.Count==6 && prepared.Select(p=>p.Id).Distinct().Count()==6 && !prepared.Any(p=>source.Any(s=>s.Id==p.Id)),"Copy IDs reused");
Need(prepared[1].X-prepared[0].X==40 && prepared.All(p=>p.Y==400),"Clipboard snapshot or group layout changed");Need(prepared[0].ObjectId==0x4F00 && prepared[5].ObjectId==0x4F05,"Special fruit identity changed");
level.Objects.AddRange(prepared);source[0].X-=8;
var before=Snapshot(level);var secondary=JsonSerializer.Serialize(level.Rooms[0].Objects,ProjectStore.Json);Need(ObjectGroups.Translate(prepared,16,32),"Move ignored");Need(prepared[1].X-prepared[0].X==40 && prepared.All(p=>p.Y==432),"Move changed spacing");Need(secondary==JsonSerializer.Serialize(level.Rooms[0].Objects,ProjectStore.Json),"Other room changed");ObjectGroups.Translate(prepared,-16,-32);Need(before==Snapshot(level),"Move reverse mismatch");
var edge=new[]{new Placement{ObjectId=0x4030,X=99990,Y=-99995},new Placement{ObjectId=0x4031,X=100000,Y=-99985}};var delta=ObjectGroups.ClampOffset(edge,100,-100);Need(delta==(0f,-5f),"Wrong group clamp");ObjectGroups.Translate(edge,100,-100);Need(edge[1].X-edge[0].X==10 && edge[1].Y-edge[0].Y==10,"Boundary distorted group");Need(!ObjectGroups.Translate(edge,10,-10),"No-op boundary changed");
Reject(()=>ObjectGroups.Copy([level.Objects.Single(p=>p.ObjectId==0x4001)],43,43));Reject(()=>ObjectGroups.Copy([level.Objects.First(p=>p.ObjectId>=0x8000)],43,43));Reject(()=>ObjectGroups.ClampOffset(source,float.NaN,0));Reject(()=>ObjectGroups.Copy([source[0],source[0]],43,43));
var cross=ObjectGroups.PreparePaste(rom,level,81,clip,240,340);Need(cross.Count==6,"Compatible secondary-room paste failed");
var pot=level.Objects.First(p=>p.ObjectId==0x4208);var potClip=ObjectGroups.Copy([pot],43,43);var unchanged=Snapshot(level);Reject(()=>ObjectGroups.PreparePaste(rom,level,81,potClip,100,100));Need(unchanged==Snapshot(level),"Rejected passage paste changed level");
var invalid=ObjectGroups.Copy([new Placement{ObjectId=0x4FFF,X=10,Y=10}],43,43);Reject(()=>ObjectGroups.PreparePaste(rom,level,43,invalid,100,100));Need(unchanged==Snapshot(level),"Rejected resource paste changed level");
var full=rom.CloneFirstLevel();while(full.Objects.Count<149){var p=rom.CreatePlacement(0x4030);p.X+=full.Objects.Count*25;full.Objects.Add(p);}var fullBefore=Snapshot(full);Reject(()=>ObjectGroups.PreparePaste(rom,full,43,clip,100,100));Need(fullBefore==Snapshot(full),"Capacity failure partially pasted");
// Preserve all six Maskass variants and bubble identities in copied groups.
var special=rom.CloneFirstLevel();special.Objects.RemoveAll(p=>p.ObjectId<0x8000 && p.ObjectId!=0x4001);var spawn=special.Objects.Single(p=>p.ObjectId==0x4001);var group=new List<Placement>();
for(int i=0;i<6;i++){var m=rom.CreatePlacement((ushort)(0x4F10+i));m.X=spawn.X+100+i*48;m.Y=spawn.Y;group.Add(m);var f=rom.CreatePlacement((ushort)(0x4F00+i));f.X=m.X;f.Y=spawn.Y-64;group.Add(f);var b=rom.CreatePlacement((ushort)(0x4F20+i));b.X=m.X;b.Y=spawn.Y-140;group.Add(b);}
special.Objects.AddRange(group);var copied=ObjectGroups.PreparePaste(rom,special,43,ObjectGroups.Copy(group,43,43),ObjectGroups.Center(group).X+384,ObjectGroups.Center(group).Y-80);special.Objects.AddRange(copied);Need(copied.Where(p=>p.HybridVariant.HasValue).Select(p=>p.HybridVariant).SequenceEqual(Enumerable.Range(0,6).Select(i=>(int?)i)),"Maskass variants lost");
Need(copied.Count(p=>ObjectCatalog.IsSpecialBubble(p.ObjectId))==6 && copied.Count(p=>ObjectCatalog.IsSpecialFruit(p.ObjectId))==6,"Special content lost");
var bytes=rom.ExportPlacements(special,true);Need(bytes[7]=='2',"V2 extension changed");File.WriteAllBytes(Path.Combine(outdir,"group-runtime.yslevel"),bytes);File.WriteAllText(Path.Combine(outdir,"group-runtime.json"),Snapshot(special));
var onlyCopies=JsonSerializer.Deserialize<LevelProject>(Snapshot(special),ProjectStore.Json)!;var sourceIds=group.Select(p=>p.Id).ToHashSet();onlyCopies.Objects.RemoveAll(p=>sourceIds.Contains(p.Id));var copiedIds=copied.Select(p=>p.Id).ToHashSet();ObjectGroups.Translate(onlyCopies.Objects.Where(p=>copiedIds.Contains(p.Id)).ToArray(),-360,80);
Need(!onlyCopies.Objects.Any(p=>sourceIds.Contains(p.Id)) && copiedIds.All(id=>onlyCopies.Objects.Any(p=>p.Id==id)),"Copied-only runtime fixture lost identities");File.WriteAllBytes(Path.Combine(outdir,"group-runtime-copied.yslevel"),rom.ExportPlacements(onlyCopies,true));File.WriteAllText(Path.Combine(outdir,"group-runtime-copied.json"),Snapshot(onlyCopies));

var store=new ProjectStore(Path.Combine(outdir,"validation-core/content"));store.Save(special);var reload=store.Levels().Single(p=>p.Id==special.Id);Need(Snapshot(reload)==Snapshot(special),"Group persistence mismatch");var clone=store.Duplicate(reload);clone.Objects.First(p=>ObjectGroups.Editable(p)).X+=1;Need(Snapshot(reload)==Snapshot(special),"Level duplicate shared group");
int templates=0;foreach(int root in VanillaRom.SourceZones){var p=rom.CloneLevel(root,false);var items=p.Objects.Where(ObjectGroups.Editable).Take(2).ToArray();p.Objects.RemoveAll(x=>ObjectGroups.Editable(x) && !items.Contains(x));var c=ObjectGroups.Center(items);var copies=ObjectGroups.PreparePaste(rom,p,root,ObjectGroups.Copy(items,root,root),c.X+24,c.Y+24);p.Objects.AddRange(copies);rom.ExportPlacements(p,true);templates++;}
File.WriteAllText(Path.Combine(outdir,"group-core.json"),JsonSerializer.Serialize(new{templates,copySnapshot=true,newIds=true,relativeSpacing=true,groupBounds=true,noOp=true,secondaryRoomIsolation=true,atomicFailures=true,specialMaskassVariants=6,specialFruits=6,specialBubbles=6,persistence=true,duplicateIsolation=true,rejected,passed=true},ProjectStore.Json));Console.WriteLine($"Group checks passed: {templates} sources, atomic capacity/resource failures, six fruits/bubbles/Maskass, snapshot and group geometry, {rejected} rejected cases.");
